(function () {
  var mc = Java.loadClass('net.minecraft.client.Minecraft').getInstance();
  var ItemStack = Java.loadClass('net.minecraft.world.item.ItemStack');
  var Screen = Java.loadClass('net.minecraft.client.gui.screens.Screen');
  var Component = Java.loadClass('net.minecraft.network.chat.Component');
  var Reg = Java.loadClass('net.minecraft.core.registries.BuiltInRegistries');
  var ID = 'astral_dice:abyss_reagent_chip';
  var item = AutoJS.item(ID);
  var stack = new ItemStack(item);
  var name = String(stack.getHoverName().getString());
  var count = 0;
  try {
    var inv = mc.player.getInventory();
    for (var k = 0; k < inv.getContainerSize(); k++) {
      var s = inv.getItem(k);
      if (!s.isEmpty() && String(Reg.ITEM.getKey(s.getItem())) === ID) { count += s.getCount(); }
    }
  } catch (e2) { count = -1; }
  var lines = [];
  var path = 'screen';
  try {
    var tip = Screen.getTooltipFromItem(mc, stack);
    for (var i = 0; i < tip.size(); i++) { lines.push(String(tip.get(i).getString())); }
  } catch (e1) {
    path = 'hoverName';
    lines.push(name);
  }
  console.info('[REL150] chip id=' + ID + ' count=' + count + ' name=' + name + ' tipn=' + lines.length + ' path=' + path);
  for (var j = 0; j < lines.length; j++) { console.info('[REL150] tip i=' + j + ' text=' + lines[j]); }
  var guide = String(Component.translatable('astral_dice.guide.entry.abyss_reagent_chip.1').getString());
  console.info('[REL150] guide key=astral_dice.guide.entry.abyss_reagent_chip.1 text=' + guide);
  return { ok: true, name: name, count: count, tipn: lines.length, path: path };
})()

(function () {
  var mc = Java.loadClass('net.minecraft.client.Minecraft').getInstance();
  var InvScreen = Java.loadClass('net.minecraft.client.gui.screens.inventory.InventoryScreen');
  var Reg = Java.loadClass('net.minecraft.core.registries.BuiltInRegistries');
  var GLFW = Java.loadClass('org.lwjgl.glfw.GLFW');
  var ID = 'astral_dice:abyss_reagent_chip';
  var out = { ok: false, open: 0, slot: -1, guiX: 0, guiY: 0, winX: 0, winY: 0, creative: 0, glfw: 0 };
  try {
    mc.setScreen(new InvScreen(mc.player));
    var scr = mc.screen;
    out.open = 1;
    out.creative = (String(scr).indexOf('CreativeModeInventoryScreen') >= 0) ? 1 : 0;
    var lx = -1, ty = -1;
    try {
      var c = scr.getClass();
      var guard = 0;
      while (c != null && String(c.getName()).indexOf('AbstractContainerScreen') < 0 && guard < 12) { c = c.getSuperclass(); guard++; }
      var fx = c.getDeclaredField('leftPos'); fx.setAccessible(true); lx = fx.getInt(scr);
      var fy = c.getDeclaredField('topPos'); fy.setAccessible(true); ty = fy.getInt(scr);
    } catch (e9) { out.reflErr = String(e9); }
    var slots = scr.getMenu().slots;
    var sx = -1, sy = -1;
    for (var i = 0; i < slots.size(); i++) {
      var st = slots.get(i).getItem();
      if (!st.isEmpty() && String(Reg.ITEM.getKey(st.getItem())) === ID) { out.slot = i; sx = slots.get(i).x + 8; sy = slots.get(i).y + 8; break; }
    }
    if (sx < 0) { sx = 16; sy = (out.creative === 1) ? 120 : 150; }
    if (lx < 0) { var gw = mc.getWindow().getGuiScaledWidth(), gh = mc.getWindow().getGuiScaledHeight();
      var iw = (out.creative === 1) ? 195 : 176, ih = (out.creative === 1) ? 136 : 166;
      lx = Math.floor((gw - iw) / 2); ty = Math.floor((gh - ih) / 2); }
    out.guiX = Math.round(lx + sx); out.guiY = Math.round(ty + sy);
    var scale = mc.getWindow().getGuiScale();
    out.winX = Math.round(out.guiX * scale); out.winY = Math.round(out.guiY * scale);
    try { var gctx = GLFW.glfwGetCurrentContext(); GLFW.glfwShowWindow(gctx); GLFW.glfwFocusWindow(gctx); GLFW.glfwSetCursorPos(gctx, out.winX, out.winY); out.glfw = 1; } catch (e4) { out.glfwErr = String(e4); }
    try { var mh = mc.mouseHandler;
      var f1 = mh.getClass().getDeclaredField('xpos'); f1.setAccessible(true); f1.setDouble(mh, out.guiX);
      var f2 = mh.getClass().getDeclaredField('ypos'); f2.setAccessible(true); f2.setDouble(mh, out.guiY);
    } catch (e2) { out.mhErr = String(e2); }
    try { scr.mouseMoved(out.guiX, out.guiY); } catch (e3) { out.mmErr = String(e3); }
    out.ok = true;
    console.info('[REL150] inventory open=1 hover=' + out.guiX + ',' + out.guiY + ' slot=' + out.slot + ' creative=' + out.creative + ' glfw=' + out.glfw + ' win=' + out.winX + ',' + out.winY);
  } catch (e0) {
    out.err = String(e0);
    console.info('[REL150] inventory open=0 hover=skip err=' + e0);
  }
  return out;
})()

